  "p.demo.f_joint_risk_d":
    "Các rủi ro tác động thế nào đến ngày kết thúc và chi phí, cùng nhau.",
  "p.demo.f_financials_t": "Tài chính",
  "p.demo.f_financials_d":
    "Ngân sách, chi tiêu thực tế và chênh lệch trên toàn danh mục.",
  "p.demo.f_cost_risk_t": "Rủi ro chi phí",
  "p.demo.f_cost_risk_d": "Độ phân tán của chi phí khả dĩ, kèm P50 và P80.",
  "p.demo.f_ledger_t": "Sổ cái cấp vốn",
  "p.demo.f_ledger_d":
    "Một khoản tài trợ và một khoản dự phòng, được truy vết đến các dòng ngân sách sử dụng chúng. Tiền chưa được lập kế hoạch trên một dòng được hiển thị là chưa truy vết.",
  "p.demo.f_costs_t": "Chi phí của một dự án",
  "p.demo.f_costs_d":
    "Chi phí nhân công từ các bảng đơn giá, và các chi phí khác theo nhiệm vụ.",
  "p.demo.f_resources_t": "Nguồn lực",
  "p.demo.f_resources_d":
    "Tám người hư cấu, vai trò của họ và công việc họ được đặt lịch.",
  "p.demo.f_capacity_t": "Bản đồ nhiệt năng lực",
  "p.demo.f_capacity_d":
    "Nguồn cung và nhu cầu theo nhóm kỹ năng và tháng. Các tháng đỏ cho thấy nơi các kỹ sư tín hiệu đang thiếu.",
  "p.demo.f_key_persons_t": "Nhân sự chủ chốt",
  "p.demo.f_key_persons_d":
    "Các điểm lỗi đơn: một kỹ sư mà chưa ai thay thế được, và một vai trò đã có người kế nhiệm sẵn sàng.",
  "p.demo.f_objectives_t": "Mục tiêu",
  "p.demo.f_objectives_d":
    "Ba mục tiêu, mỗi mục tiêu gắn với các kế hoạch phục vụ nó.",
  "p.demo.f_okrs_t": "Mục tiêu và kết quả then chốt",
  "p.demo.f_okrs_d": "Các kết quả then chốt kèm lần kiểm tra và độ tin cậy.",
  "p.demo.f_kpis_t": "Thước đo chính",
  "p.demo.f_kpis_d":
    "Số phút chậm trễ, mức hài lòng của hành khách và chi tiêu so với kế hoạch, kèm số đo mỗi tháng.",
  "p.demo.f_proposals_t": "Tiếp nhận công việc",
  "p.demo.f_proposals_d":
    "Năm đề xuất ở các giai đoạn khác nhau, từ soạn nháp đến được phê duyệt và bị từ chối.",
  "p.demo.f_ideas_t": "Ý tưởng",
  "p.demo.f_ideas_d":
    "Bốn ý tưởng có bình chọn. Hãy chuyển một ý tưởng thành đề xuất.",
  "p.demo.f_scenarios_t": "Kịch bản",
  "p.demo.f_scenarios_d":
    "Những gì vừa trong giới hạn ngân sách nếu công việc tín hiệu được làm trước.",
  "p.demo.f_director_packs_t": "Gói báo cáo giám đốc",
  "p.demo.f_director_packs_d":
    "Các gói cho điều hành và ban giám đốc tháng Chín, được tổng hợp từ dữ liệu trực tiếp. Hãy mở một gói để xem từng phần.",
  "p.demo.f_organizations_t": "Tổ chức đối tác",
  "p.demo.f_organizations_d":
    "Cơ quan, đơn vị triển khai của nó, một đối tác và một nhà cung cấp.",
  "p.demo.f_milestone_signoffs_t": "Ký duyệt cột mốc",
  "p.demo.f_milestone_signoffs_d":
    "Vận hành chính thức cần đối tác và nhà cung cấp ký. Nhà cung cấp đã ký; đối tác chưa, nên vận hành chính thức được giao nhưng chưa đạt.",
  "p.demo.f_cutover_t": "Chuyển đổi: tiến hành hay dừng",
  "p.demo.f_cutover_d":
    "Ba tiêu chí dừng, một tiêu chí đạt, một đồng ký tên đã có. Tiến hành sẽ bị từ chối, và màn hình nêu lý do.",
  "p.demo.f_deployment_moves_t": "Dời lịch triển khai",
  "p.demo.f_deployment_moves_d":
    "Một yêu cầu dời ngày bắt đầu lắp đặt hai tuần, kèm ảnh hưởng dây chuyền lên các nhiệm vụ khác và chi phí nhân công, đang chờ phê duyệt.",
  "p.demo.f_start_queue_t": "Hàng đợi bắt đầu",
  "p.demo.f_start_queue_d":
    "Hai chương trình đang triển khai và giới hạn là hai, nên chương trình thứ ba chờ trong hàng đợi, theo thứ tự.",
  "p.demo.f_critical_chain_t": "Chuỗi găng",
  "p.demo.f_critical_chain_d":
    "Chuỗi đi qua các nhiệm vụ phụ thuộc và những người họ dùng chung, kèm ước tính tích cực và ước tính an toàn.",
  "p.demo.f_buffers_t": "Quản lý vùng đệm",
  "p.demo.f_buffers_d":
    "Kế hoạch vùng đệm đã cố định, biểu đồ sốt và một hành động khắc phục.",
  "p.demo.f_pipeline_t": "Trống và đường ống",
  "p.demo.f_pipeline_d":
    "Nhóm kỹ năng mà danh mục phụ thuộc nhiều nhất, và các thời điểm bắt đầu so le được đề xuất.",
  "p.demo.f_search_t": "Tìm kiếm",
