  "p.cutover.lede":
    "Quyết định chuyển đổi một hệ thống quan trọng về an toàn. Các tiêu chí dừng được viết và công bố trước, rồi được cố định: thay đổi chúng sẽ tạo phiên bản mới. Tiến hành cần mọi tiêu chí đạt và mọi đồng ký tên bắt buộc. Quyết định dừng, hoặc hoãn vì an toàn, là quyết định dựa trên các tiêu chí; đó không phải là trượt tiến độ.",
