  "p.access.heading": "Rà soát quyền truy cập và truy cập khẩn cấp",
  "p.access.intro":
    "Phần rà soát quyền truy cập liệt kê các quyền truy cập mà mọi người đã ghi nhận là được cấp, để chứng nhận lại. Truy cập khẩn cấp mở một kế hoạch riêng tư cho bạn trong thời gian giới hạn khi không còn cách nào khác; mọi lần sử dụng đều được ghi lại và kiểm toán.",
  "p.access.review_heading": "Rà soát quyền truy cập",
  "p.access.review_intro":
    "Các quyền truy cập được ghi nhận là đã cấp trong sổ cái truy cập và chưa bị thu hồi, cũ nhất trước, kèm người cấp và thời điểm cấp. Danh sách cho thấy những gì mọi người đã ghi nhận, không phải những gì dịch vụ đăng nhập thực thi: hãy đối chiếu hai bên. Chỉ dành cho quản trị viên; mỗi lần đọc đều được ghi vào nhật ký kiểm toán, nên phần rà soát chỉ được đọc khi bạn yêu cầu.",
