  "p.frontier.says":
    "Bộ sinh chấm điểm từng kế hoạch bạn có thể đọc theo Smart Score và định giá theo các dòng ngân sách của kế hoạch, rồi lấy các kế hoạch theo điểm trên mỗi đơn vị chi phí cho đến khi hết mức trần. Các kế hoạch bắt buộc phải có được lấy trước, bất kể chi phí. Kế hoạch không có Smart Score bị loại; kế hoạch không có dòng ngân sách thì chi phí bằng không. Lựa chọn không phải lúc nào cũng tốt nhất có thể, nên mức trần mua được không thêm giá trị so với mức trần rẻ hơn sẽ được đánh dấu, không bị ẩn.",
