  "p.feed.heading": "Nguồn cấp lịch",
  "p.feed.says":
    "Một địa chỉ riêng tư mà ứng dụng lịch có thể đăng ký: các nhiệm vụ đang mở giao cho bạn có hạn, các cột mốc và sprint của các kế hoạch đó, và thời gian bạn đã lên kế hoạch. Một địa chỉ thứ hai là nguồn cấp các thông báo của bạn cho trình đọc nguồn cấp. Ai có địa chỉ cũng đọc được những gì nó hiển thị, nên hãy giữ riêng cho mình.",
