  "p.hammock.heading": "Hammock: nhiệm vụ tóm lược bao trùm các nhiệm vụ khác",
  "p.hammock.says":
    "Hammock là một nhiệm vụ tóm lược có ngày lấy từ các nhiệm vụ của kế hoạch này mà nó liên kết, từ ngày bắt đầu sớm nhất đến ngày kết thúc muộn nhất. Nó không nằm trong mạng phụ thuộc, nên không bao giờ thay đổi độ trễ cho phép của nhiệm vụ nào hay ngày kết thúc. Một nhiệm vụ chỉ trở thành hammock khi không có thời lượng, khối lượng công việc, ràng buộc hay phụ thuộc, và ngày bắt đầu kế hoạch của nó bị xóa; biến nó về lại nhiệm vụ sẽ gỡ mọi liên kết của nó. Một hammock liên kết tới một nhiệm vụ hoặc hammock khác của kế hoạch này, không liên kết tới chính nó, không liên kết hai lần và không tạo vòng lặp.",
