  "p.ccpm.heading": "Ước tính quyết liệt và an toàn",
  "p.ccpm.says":
    "Với chuỗi găng, mỗi nhiệm vụ cần một ước tính quyết liệt (xác suất gần bằng một nửa) và một ước tính an toàn, tính bằng ngày làm việc nguyên từ 1 đến {max}, ước tính quyết liệt không lớn hơn ước tính an toàn. Con số hiển thị là số đã ghi nhận, nếu không thì là số từ khoảng rủi ro, nếu không thì là số do quy tắc của hệ thống triển khai suy ra, và mỗi con số cho biết nguồn. Cột mốc và nhiệm vụ không có thời lượng không được ước tính. Xóa cả hai sẽ gỡ những gì đã ghi nhận.",
